public class ProfileTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Profile p = new Profile("Ana", 3);
        check("withLevel makes a modified copy", "Profile[name=Ana, level=4]",
                String.valueOf(p.withLevel(4)));
        check("withName makes a modified copy", "Profile[name=Bo, level=3]",
                String.valueOf(p.withName("Bo")));
        check("wither result equals a fresh record", new Profile("Bo", 3), p.withName("Bo"));
        check("original is untouched", "Profile[name=Ana, level=3]", String.valueOf(p));
        check("display", "Ana [3]", p.display());
        try {
            check("withers chain", "Cy [9]", p.withName("Cy").withLevel(9).display());
        } catch (Exception e) {
            check("withers chain", "Cy [9]", "threw " + e.getClass().getSimpleName());
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

