public record Profile(String name, int level) {

    public Profile withName(String newName) {
        return new Profile(newName, level);
    }

    public Profile withLevel(int newLevel) {
        return new Profile(name, newLevel);
    }

    public String display() {
        return name + " [" + level + "]";
    }
}
